import pandas as pd
import numpy as np
from datetime import datetime
import json
import os

# Create output directory
os.makedirs('/app/output', exist_ok=True)

# 1. Load Data
df = pd.read_csv('/app/benchmark/data.csv')

# 2. Data Cleaning
# For pricing analysis, drop missing prices
df_price = df.dropna(subset=['price']).copy()
# Remove any non-positive prices if any
df_price = df_price[df_price['price'] > 0]

# 3. Calculate KPIs per city
cities = df['city'].unique()

# Aggregations
# Total listings per city
total_listings = df.groupby('city').size()

# Median Nightly Price by City
median_price = df_price.groupby('city')['price'].median()

# Average Nightly Price by City
mean_price = df_price.groupby('city')['price'].mean()

# Professional Host Share (>= 5 listings)
prof_host_count = df[df['calculated_host_listings_count'] >= 5].groupby('city').size()
prof_host_share = (prof_host_count / total_listings * 100).fillna(0)

# Average Reviews per Month
avg_reviews_pm = df['reviews_per_month'].dropna().groupby(df['city']).mean()

# Mean Availability
mean_availability = df.groupby('city')['availability_365'].mean()

# Entire Home Share
entire_home_count = df[df['room_type'] == 'Entire home/apt'].groupby('city').size()
entire_home_share = (entire_home_count / total_listings * 100).fillna(0)

# Combine into a summary dataframe
city_stats = pd.DataFrame({
    'Total Listings': total_listings,
    'Median Price ($)': median_price,
    'Average Price ($)': mean_price,
    'Prof. Host Share (%)': prof_host_share,
    'Entire Home Share (%)': entire_home_share,
    'Avg Reviews/Month': avg_reviews_pm,
    'Mean Availability (days)': mean_availability
}).round(2).sort_values('Median Price ($)', ascending=False)

# 4. Room Type Distribution
room_type_dist = df.groupby(['city', 'room_type']).size().unstack(fill_value=0)
room_type_dist_pct = room_type_dist.div(room_type_dist.sum(axis=1), axis=0) * 100

# Top 10 cities ordered by median price for charts
sorted_cities = city_stats.index.tolist()

# 5. Generate HTML content
def generate_chart_js():
    chart_data_price = {
        'labels': json.dumps(sorted_cities),
        'data': json.dumps(city_stats['Median Price ($)'].tolist())
    }

    chart_data_prof = {
        'labels': json.dumps(sorted_cities),
        'data': json.dumps(city_stats['Prof. Host Share (%)'].tolist())
    }

    chart_data_reviews = {
        'labels': json.dumps(sorted_cities),
        'data': json.dumps(city_stats['Avg Reviews/Month'].tolist())
    }

    # Prepare stacked bar chart data for room types
    room_types = room_type_dist_pct.columns.tolist()
    datasets = []
    colors = ['#3498db', '#2ecc71', '#e74c3c', '#f1c40f']
    for i, rt in enumerate(room_types):
        datasets.append({
            'label': rt,
            'data': room_type_dist_pct.loc[sorted_cities, rt].tolist(),
            'backgroundColor': colors[i % len(colors)]
        })

    stacked_datasets_json = json.dumps(datasets)

    return f"""
    <script>
        // Median Price Chart
        new Chart(document.getElementById('chart_price'), {{
            type: 'bar',
            data: {{
                labels: {chart_data_price['labels']},
                datasets: [{{
                    label: 'Median Nightly Price ($)',
                    data: {chart_data_price['data']},
                    backgroundColor: 'rgba(52, 152, 219, 0.7)',
                    borderColor: 'rgba(52, 152, 219, 1)',
                    borderWidth: 1
                }}]
            }},
            options: {{ responsive: true, scales: {{ y: {{ beginAtZero: true }} }} }}
        }});

        // Professional Host Share Chart
        new Chart(document.getElementById('chart_prof_host'), {{
            type: 'bar',
            data: {{
                labels: {chart_data_prof['labels']},
                datasets: [{{
                    label: 'Professional Host Share (%)',
                    data: {chart_data_prof['data']},
                    backgroundColor: 'rgba(155, 89, 182, 0.7)',
                    borderColor: 'rgba(155, 89, 182, 1)',
                    borderWidth: 1
                }}]
            }},
            options: {{ responsive: true, scales: {{ y: {{ beginAtZero: true }} }} }}
        }});

        // Room Type Distribution Chart
        new Chart(document.getElementById('chart_room_type'), {{
            type: 'bar',
            data: {{
                labels: {json.dumps(sorted_cities)},
                datasets: {stacked_datasets_json}
            }},
            options: {{ 
                responsive: true, 
                scales: {{ 
                    x: {{ stacked: true }},
                    y: {{ stacked: true, beginAtZero: true, max: 100 }} 
                }} 
            }}
        }});

        // Avg Reviews Chart
        new Chart(document.getElementById('chart_reviews'), {{
            type: 'bar',
            data: {{
                labels: {chart_data_reviews['labels']},
                datasets: [{{
                    label: 'Average Reviews per Month',
                    data: {chart_data_reviews['data']},
                    backgroundColor: 'rgba(46, 204, 113, 0.7)',
                    borderColor: 'rgba(46, 204, 113, 1)',
                    borderWidth: 1
                }}]
            }},
            options: {{ responsive: true, scales: {{ y: {{ beginAtZero: true }} }} }}
        }});
    </script>
    """

# Overall KPIs
global_median_price = df_price['price'].median()
